fragmentVersions.css:
.acme-hours {
	align-items: center;
	background: linear-gradient(135deg, #fff7ec, #fbe3c4);
	border-radius: 24px;
	display: flex;
	font-family: Georgia, serif;
	gap: 32px;
	margin: 24px auto;
	max-width: 960px;
	padding: 32px 40px;
}

.acme-hours__icon {
	color: var(--acme-accent);
	flex: 0 0 140px;
	height: 140px;
	width: 140px;
}

.acme-hours__body {
	flex: 1;
}

.acme-hours__eyebrow {
	color: var(--acme-accent);
	font-size: 14px;
	font-weight: 700;
	letter-spacing: 0.12em;
	margin: 0 0 8px;
	text-transform: uppercase;
}

.acme-hours__title {
	color: #3b1f0e;
	font-size: 40px;
	margin: 0 0 16px;
}

.acme-hours__list {
	margin: 0 0 20px;
}

.acme-hours__row {
	border-bottom: 1px dashed rgba(92, 59, 36, 0.3);
	display: flex;
	gap: 16px;
	justify-content: space-between;
	padding: 10px 0;
}

.acme-hours__day {
	color: #5c3b24;
	font-size: 18px;
	margin: 0;
}

.acme-hours__time {
	color: #3b1f0e;
	font-family: system-ui, sans-serif;
	font-size: 18px;
	font-weight: 600;
	margin: 0;
}

.acme-hours__cta {
	background: var(--acme-accent);
	border-radius: 999px;
	color: #fff;
	display: inline-block;
	font-family: system-ui, sans-serif;
	font-weight: 600;
	padding: 12px 24px;
}

@media (max-width: 600px) {
	.acme-hours {
		flex-direction: column;
		padding: 24px;
		text-align: center;
	}

	.acme-hours__icon {
		flex-basis: 96px;
		height: 96px;
		width: 96px;
	}

	.acme-hours__row {
		flex-direction: column;
		gap: 4px;
	}
}
